import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(0)
        return

    n = int(data[0])
    k = int(data[1])

    if n == 0:
        print(1 if k == 0 else 0)
        return

    arr = list(map(int, data[2:2+n]))

    dp = [0] * (k + 1)
    dp[0] = 1

    for num in arr:
        for j in range(k, num - 1, -1):
            dp[j] += dp[j - num]

    print(dp[k])

if __name__ == "__main__":
    main()
